## Code Example
```javascript
class SegTree {
  constructor(n){ this.n=n; this.min=Array(4*n).fill(0); this.cover=Array(4*n).fill(0); this.lazy=Array(4*n).fill(0); }
  _apply(i,delta){ this.cover[i]+=delta; this.min[i]+=delta; this.lazy[i]+=delta; }
  _push(i){ if(this.lazy[i]!==0){ this._apply(i*2,this.lazy[i]); this._apply(i*2+1,this.lazy[i]); this.lazy[i]=0; } }
  update(qL,qR,delta,i=1,l=0,r=this.n-1){ if(qR<l||r<qL) return; if(qL<=l&&r<=qR){ this._apply(i,delta); return; } this._push(i); const m=(l+r)>>1; this.update(qL,qR,delta,i*2,l,m); this.update(qL,qR,delta,i*2+1,m+1,r); this.min[i]=Math.min(this.min[i*2],this.min[i*2+1]); }
  fullCovered(){ return this.min[1]>0; }
}
``` 

